set-variable.value:
@{
    var summary = new JObject {
      ["scoring_status"] = JValue.CreateNull(), ["schema_valid"] = false,
      ["body_within_bound"] = false, ["key_types"] = new JObject(),
      ["probabilities"] = JValue.CreateNull(),
      ["usage"] = new JObject { ["input_tokens"] = JValue.CreateNull(), ["output_tokens"] = JValue.CreateNull(), ["total_tokens"] = JValue.CreateNull() }
    };
    try {
      var response = context.Variables.GetValueOrDefault<IResponse>("auto-diagnostic-response", null);
      if (response == null) { return summary.ToString(Newtonsoft.Json.Formatting.None); }
      summary["scoring_status"] = response.StatusCode;
      long length;
      if (!long.TryParse(response.Headers.GetValueOrDefault("Content-Length", ""), out length) || length < 0 || length > 65536) { return summary.ToString(Newtonsoft.Json.Formatting.None); }
      var raw = response.Body.As<string>(preserveContent: false);
      if (raw == null || System.Text.Encoding.UTF8.GetByteCount(raw) > 65536) { return summary.ToString(Newtonsoft.Json.Formatting.None); }
      summary["body_within_bound"] = true;
      var result = JObject.Parse(raw);
      var types = new JObject();
      foreach (var name in new [] { "answers", "usage", "model", "id", "error" }) {
        if (result[name] != null) { types[name] = result[name].Type.ToString(); }
      }
      summary["key_types"] = types;
      var answers = result["answers"] as JObject;
      var answer = answers == null ? null : answers["route"] as JObject;
      var probabilities = answer == null ? null : answer["probabilities"] as JObject;
      if (response.StatusCode == 200 && answer != null && (string)answer["type"] == "choice" && probabilities != null && probabilities.Properties().Count() == 2) {
        var good = true;
        var sum = 0.0;
        var safe = new JObject();
        foreach (var name in new [] { "greeting", "arithmetic" }) {
          var score = probabilities[name];
          if (score == null || (score.Type != JTokenType.Float && score.Type != JTokenType.Integer) || !((double)score >= 0 && (double)score <= 1)) { good = false; break; }
          safe[name] = (double)score;
          sum += (double)score;
        }
        if (good && Math.Abs(sum - 1.0) <= 0.02) { summary["probabilities"] = safe; summary["schema_valid"] = true; }
      }
      var usage = result["usage"] as JObject;
      if (usage != null) {
        foreach (var name in new [] { "input_tokens", "output_tokens", "total_tokens" }) {
          var number = usage[name];
          if (number != null && number.Type == JTokenType.Integer && (long)number >= 0 && (long)number <= 2147483647) { summary["usage"][name] = (long)number; }
        }
      }
    } catch { }
    return summary.ToString(Newtonsoft.Json.Formatting.None);
  }
